import React, { useEffect, useState } from 'react';
import { Card, api, Badge } from '../App';

const Stat = ({ label, value, color = '#1a3c5e' }) => (
  <div style={{ background:'#fff', borderRadius:8, padding:'20px 24px', boxShadow:'0 1px 4px rgba(0,0,0,0.08)', flex:1, minWidth:140 }}>
    <div style={{ fontSize:28, fontWeight:700, color }}>{value ?? '—'}</div>
    <div style={{ fontSize:12, color:'#888', marginTop:4 }}>{label}</div>
  </div>
);

export default function Dashboard() {
  const [dash, setDash]       = useState(null);
  const [logs, setLogs]       = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      api.get('/reports/dashboard'),
      api.get('/import/logs')
    ]).then(([d, l]) => {
      setDash(d.data);
      setLogs(l.data);
    }).finally(() => setLoading(false));
  }, []);

  if (loading) return <div style={{ padding:40, color:'#999' }}>Loading…</div>;

  return (
    <div>
      <h2 style={{ marginBottom:20, color:'#1a3c5e' }}>🍵 Tea Auction Dashboard</h2>

      <div style={{ display:'flex', gap:16, marginBottom:24, flexWrap:'wrap' }}>
        <Stat label="Total Parties"       value={dash?.total_parties}       color="#1a3c5e" />
        <Stat label="Confirmed Markings"  value={dash?.confirmed_markings}  color="#1a7a4a" />
        <Stat label="Imports This Week"   value={dash?.imports_this_week}   color="#b45309" />
        <Stat label="Recent Sales"        value={dash?.recent_sales?.length} color="#6d28d9" />
      </div>

      <Card>
        <h3 style={{ marginBottom:14, fontSize:15 }}>Recent Sale Numbers</h3>
        <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
          {dash?.recent_sales?.map(s => (
            <Badge key={s} color="blue">{s}</Badge>
          ))}
          {(!dash?.recent_sales?.length) && <span style={{ color:'#999', fontSize:13 }}>No sales imported yet</span>}
        </div>
      </Card>

      <Card>
        <h3 style={{ marginBottom:14, fontSize:15 }}>Recent Imports</h3>
        <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
          <thead>
            <tr style={{ background:'#f0f4f8' }}>
              {['Type','File','Sale No','Imported','Skipped','Date'].map(h => (
                <th key={h} style={{ padding:'7px 10px', textAlign:'left', fontWeight:600, color:'#444', borderBottom:'2px solid #e2e8f0' }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {logs.length === 0 ? (
              <tr><td colSpan={6} style={{ padding:20, textAlign:'center', color:'#999' }}>No imports yet. Start by uploading a Catalogue file.</td></tr>
            ) : logs.map((l, i) => (
              <tr key={i} style={{ borderBottom:'1px solid #f0f4f8' }}>
                <td style={{ padding:'7px 10px' }}><Badge color={l.file_type==='catalogue'?'blue':'green'}>{l.file_type}</Badge></td>
                <td style={{ padding:'7px 10px', maxWidth:180, overflow:'hidden', textOverflow:'ellipsis' }}>{l.filename}</td>
                <td style={{ padding:'7px 10px' }}>{l.sale_no || '—'}</td>
                <td style={{ padding:'7px 10px', color:'#1a7a4a', fontWeight:600 }}>{l.rows_imported}</td>
                <td style={{ padding:'7px 10px', color: l.rows_skipped>0?'#c0392b':'#888' }}>{l.rows_skipped}</td>
                <td style={{ padding:'7px 10px', color:'#888' }}>{new Date(l.imported_at).toLocaleString('en-IN')}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>

      <Card style={{ background:'#fffbeb', border:'1px solid #fde68a' }}>
        <h3 style={{ marginBottom:10, fontSize:14, color:'#92400e' }}>📌 Workflow</h3>
        <div style={{ display:'flex', gap:0, flexWrap:'wrap' }}>
          {['1. Import Catalogue (Thursday)', '2. Import Sold List', '3. Set Party Mappings', '4. Create Markings', '5. Print Labels'].map((step, i, arr) => (
            <div key={i} style={{ display:'flex', alignItems:'center' }}>
              <span style={{ background:'#1a3c5e', color:'#fff', padding:'4px 12px', borderRadius:4, fontSize:12, fontWeight:600 }}>{step}</span>
              {i < arr.length-1 && <span style={{ margin:'0 6px', color:'#ccc', fontSize:18 }}>→</span>}
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}
